template:
% 参数由系统自动注入：\def\radius{3} \def\anglea{30} \def\showradius{1} \def\showtangent{1} \def\showpoint{0} \def\labelt{T} \def\labelp{P} \def\ptlen{2.5}
% 视觉归一化：把圆直径缩放到 6cm，保证图形视觉大小稳定。
\pgfmathsetmacro{\figscale}{3 / \radius}
% 装饰尺寸：scale= 会同时缩放坐标和 pt 单位长度，故绝对尺寸除以 figscale 抵消，保证视觉大小恒定。
\pgfmathsetmacro{\dotr}{1.6/\figscale}
\pgfmathsetmacro{\Tx}{\radius*cos(\anglea)}
\pgfmathsetmacro{\Ty}{\radius*sin(\anglea)}
\pgfmathsetmacro{\tdx}{cos(\anglea+90)}
\pgfmathsetmacro{\tdy}{sin(\anglea+90)}
% 切线半长：按半径成比例（等价于 3.3/figscale），保证视觉长度恒定；打开外点 P 时延长到覆盖 P
\pgfmathsetmacro{\tlen}{max(\radius*1.1, \showpoint*\ptlen*1.1)}
\begin{tikzpicture}[scale=\figscale, every node/.style={font=\small, fill=none, inner sep=1.5pt}]
  \coordinate (O) at (0,0);
  \coordinate (T) at (\Tx,\Ty);
  % 圆
  \draw[thick] (O) circle [radius=\radius];
  % 切线 l：过切点 T 沿垂直于 OT 的方向向两侧延伸
  \ifnum\showtangent>0
    \draw[thick] ({\Tx + \tlen*\tdx},{\Ty + \tlen*\tdy}) -- ({\Tx - \tlen*\tdx},{\Ty - \tlen*\tdy});
    \node[left=2pt] at ({\Tx - 0.82*\tlen*\tdx},{\Ty - 0.82*\tlen*\tdy}) {$l$};
  \fi
  % 切点半径 OT + 直角记号（OT 与切线垂直）
  \ifnum\showradius>0
    \draw[thick] (O) -- (T);
    \pgfmathsetmacro{\rs}{min(0.28/\figscale, \radius*0.16)}
    \pgfmathsetmacro{\qax}{\Tx - \rs*cos(\anglea)}
    \pgfmathsetmacro{\qay}{\Ty - \rs*sin(\anglea)}
    \pgfmathsetmacro{\qbx}{\Tx + \rs*\tdx}
    \pgfmathsetmacro{\qby}{\Ty + \rs*\tdy}
    \pgfmathsetmacro{\qcx}{\qax + \rs*\tdx}
    \pgfmathsetmacro{\qcy}{\qay + \rs*\tdy}
    \draw[thick] (\qax,\qay) -- (\qcx,\qcy) -- (\qbx,\qby);
  \fi
  % 切点 T（恒标注，与是否画半径无关）
  \fill (T) circle [radius=\dotr pt];
  \node at ({1.15*\Tx},{1.15*\Ty}) {$\labelt$};
  % 外点 P 与切线长 PT（沿切线方向）
  \ifnum\showpoint>0
    \pgfmathsetmacro{\Px}{\Tx + \ptlen*\tdx}
    \pgfmathsetmacro{\Py}{\Ty + \ptlen*\tdy}
    \coordinate (P) at (\Px,\Py);
    \draw[thick] (T) -- (P);
    \fill (P) circle [radius=\dotr pt];
    \node[above right=3pt] at (P) {$\labelp$};
  \fi
  % 圆心 O
  \fill (O) circle [radius=\dotr pt];
  \node[below left=3pt] at (O) {$O$};
\end{tikzpicture}
